public String isValid(String s) {
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) freq[s.charAt(i) - 'a']++;
    Map<Integer, Integer> ffreq = new HashMap<>();
    for (int f : freq) {
        if (f > 0) ffreq.merge(f, 1, Integer::sum);
    }
    if (ffreq.size() == 1) return "YES";
    if (ffreq.size() == 2) {
        List<Integer> keys = new ArrayList<>(ffreq.keySet());
        Collections.sort(keys);
        int lo = keys.get(0), hi = keys.get(1);
        if (lo == 1 && ffreq.get(lo) == 1) return "YES";
        if (hi - lo == 1 && ffreq.get(hi) == 1) return "YES";
    }
    return "NO";
}

