def isValid(self, s: str) -> str:
    from collections import Counter
    freq = Counter(s)
    ffreq = Counter(freq.values())
    if len(ffreq) == 1:
        return "YES"
    if len(ffreq) == 2:
        lo, hi = sorted(ffreq)
        if lo == 1 and ffreq[lo] == 1:
            return "YES"
        if hi - lo == 1 and ffreq[hi] == 1:
            return "YES"
    return "NO"

